import sys
import math

MOD = 998244353
base = 3

def power(a, n):
    res = 1
    a %= MOD
    while n > 0:
        if n & 1:
            res = (res * a) % MOD
        a = (a * a) % MOD
        n >>= 1
    return res

def shuffle(arr, length):
    j = length // 2
    for i in range(1, length - 1):
        if i < j:
            arr[i], arr[j] = arr[j], arr[i]
        k = length // 2
        while j >= k:
            j -= k
            k //= 2
        if j < k:
            j += k

def fft(arr, length, dir):
    shuffle(arr, length)
    h = 2
    while h <= length:
        wlen = power(base, (MOD - 1) // h)
        if dir == -1:
            wlen = power(wlen, MOD - 2)
        for start in range(0, length, h):
            w = 1
            for k in range(start, start + h // 2):
                u = arr[k]
                v = arr[k + h // 2] * w % MOD
                arr[k] = (u + v) % MOD
                arr[k + h // 2] = (u - v + MOD) % MOD
                w = w * wlen % MOD
        h <<= 1
    if dir == -1:
        inv = power(length, MOD - 2)
        for i in range(length):
            arr[i] = arr[i] * inv % MOD

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    halfN = n // 2
    len_power = 1
    while len_power < (9 * halfN + 1):
        len_power <<= 1
    arr = [0] * len_power
    for i in range(m):
        x = int(input_data[2 + i])
        arr[x] = 1
    fft(arr, len_power, 1)
    for i in range(len_power):
        if arr[i] != 0:
            arr[i] = power(arr[i], halfN) % MOD
    fft(arr, len_power, -1)
    totalSum = 0
    for i in range(len_power):
        totalSum = (totalSum + arr[i] * arr[i]) % MOD
    print(totalSum)

if __name__ == "__main__":
    main()

